begin perform public.apply_checkout_event(shop,second);raise exception 'Disabled template accepted';exception when sqlstate 'PT409' then null;end;
execute 'reset role';update public.shop_members set role='cashier',rank=1,access_level=1 where shop_id=shop and user_id='a0000000-0000-4000-8000-000000000001';execute 'set local role authenticated';
begin perform public.save_business_settings(shop,(select version from public.business_settings where shop_id=shop),settings);raise exception 'Cashier saved templates';exception when raise_exception then if sqlerrm not like 'Developer maintenance%' then raise;end if;end;
begin perform public.apply_checkout_event(gen_random_uuid(),second);raise exception 'Cross-business checkout accepted';exception when raise_exception then if sqlerrm not like 'Business access denied%' then raise;end if;end;
execute 'reset role';
end $test$;
rollback;
